# 펠릿·숯·방부: 전국 생산량 ÷ (업체 수 × 업체 평균 최대 생산가능량) — 응답업체/모집단 차이로 참고치
def cap_based(prod,firms,avg,production,note):
    for y,f,a in zip(Y14,firms,avg):
        rows.append(dict(year=y,product=prod,metric="capacity_total",value=round(f*a),unit=("t" if prod in("p11","p15") else "m3"),source=U,note="업체 수 × 업체 평균 최대 생산가능량"))
        rows.append(dict(year=y,product=prod,metric="firms",value=f,unit="개소",source=U,note=""))
        if y in production:
            rows.append(dict(year=y,product=prod,metric="utilization_pct",value=round(production[y]/(f*a)*100,1),unit="%",source=U,note=note))
